/** Activation intents — declared, translated by adapters (0001 §3.8). */
export type Trigger = "post_link" | "post_activate" | "on_remove";
export type Intent = {
    kind: "service";
    trigger: Trigger;
    name: string;
    user: boolean;
} | {
    kind: "fonts";
    trigger: Trigger;
} | {
    kind: "desktop_entry";
    trigger: Trigger;
} | {
    kind: "custom_shell";
    trigger: Trigger;
    script: string;
};
export declare const service: (name: string, user?: boolean, trigger?: Trigger) => Intent;
export declare const fonts: (trigger?: Trigger) => Intent;
export declare const desktopEntry: (trigger?: Trigger) => Intent;
/** Escape hatch — flagged, shown by `plan`. */
export declare const customHook: (script: string, trigger?: Trigger) => Intent;
